            if not line.strip():
                continue
            if EXCLUSION_RE.search(line):
                continue
            kw_hit = False
            for kw in keywords:
                if re.search(kw, line, re.I):
                    kw_hit = True
                    break
            if not kw_hit:
                continue
            amt = _extract_amount_from_line(line)
